import type { FilterDataStructure, FilterValue } from 'models/Filters';

const POWER_PERIODS_FALLBACK_MAP: Record<string, string> = {
  L3M: 'QTD',
  MTD: 'QTD',
};

const LEGACY_PERIOD_ALIASES: Record<string, readonly string[]> = {
  LQ: ['QTD'],
  QTD: ['LQ'],
};

export const isLegacyPeriodAvailable = (
  filterData: FilterDataStructure,
  value: FilterValue,
): boolean =>
  filterData.periods?.values?.some((option) => option?.value === value) ??
  false;

const findAvailablePeriod = (
  filterData: FilterDataStructure,
  value: FilterValue,
): FilterValue | undefined => {
  const availableValues = filterData.periods?.values ?? [];
  const exactMatch = availableValues.find(
    (option) => option?.value === value,
  )?.value;

  if (exactMatch !== undefined) return exactMatch;
  if (typeof value !== 'string') return undefined;

  const aliases = LEGACY_PERIOD_ALIASES[value] ?? [];
  return availableValues.find(
    (option) =>
      typeof option?.value === 'string' && aliases.includes(option.value),
  )?.value;
};

export const areLegacyPeriodsEquivalent = (
  first: FilterValue,
  second: FilterValue,
): boolean => {
  if (first === second) return true;
  if (typeof first !== 'string' || typeof second !== 'string') return false;

  return LEGACY_PERIOD_ALIASES[first]?.includes(second) ?? false;
};

export const resolveLegacyPeriod = (
  filterData: FilterDataStructure,
  value: FilterValue,
  fallbackDefault: FilterValue = filterData.periods?.default?.value ?? null,
): FilterValue => {
  const availablePeriod = findAvailablePeriod(filterData, value);
  if (availablePeriod !== undefined) return availablePeriod;

  const fallback = POWER_PERIODS_FALLBACK_MAP[String(value ?? '')];
  const availableFallback = fallback
    ? findAvailablePeriod(filterData, fallback)
    : undefined;

  if (availableFallback !== undefined) return availableFallback;

  return findAvailablePeriod(filterData, fallbackDefault) ?? fallbackDefault;
};
